#!/usr/bin/env bun
/**
 * ZOU-401: Eval-Driven CI/CD Gate
 *
 * Runs ZouroBench, diffs against baseline, emits PASS/FAIL/WARN.
 * Exit codes: 0=PASS, 1=FAIL(>2% regression), 2=WARN(between 1-2%), 3=ERROR
 *
 * Usage:
 *   bun regression-gate.ts                  # Full 54-question run
 *   bun regression-gate.ts --quick          # 15-question sanity check
 *   bun regression-gate.ts --baseline-only  # Just update baseline, don't gate
 */
import { existsSync, readFileSync, writeFileSync, readdirSync, mkdirSync } from "fs";
import { join } from "path";
import { spawnSync } from "child_process";

const BENCH_DIR = "/home/workspace/zouroboros/packages/bench";
const RUNS_DIR = join(BENCH_DIR, "data", "runs");
const BASELINE_DIR = join(BENCH_DIR, "data", "baselines");
const ADAPTER = join(BENCH_DIR, "adapters", "zourobench-adapter.ts");
const SEED = join(BENCH_DIR, "data", "zourobench", "seed.json");
const REGRESSION_THRESHOLD = 0.02;   // 2% — anything worse triggers FAIL
const WARN_THRESHOLD = 0.01;         // 1% — triggers WARN

interface GateResult {
  overall: number;
  categories: Record<string, number>;
  // ... details omitted for brevity
}

function loadBaseline(): { timestamp: string; scores: Record<string,number> } | null {
  const dir = join(BENCH_DIR, "data", "baselines");
  if (!existsSync(dir)) return null;
  const files = readdirSync(dir).filter(f => f.endsWith(".json")).sort().reverse();
  if (!files.length) return null;
  return JSON.parse(readFileSync(join(dir, files[0]), "utf-8"));
}

function loadLatestRun(): any | null {
  if (!existsSync(RUNS_DIR)) return null;
  const files = readdirSync(RUNS_DIR).filter(f => f.startsWith("ZouroBench") && f.endsWith(".json")).sort().reverse();
  if (!files.length) return null;
  return JSON.parse(readFileSync(join(RUNS_DIR, files[0]), "utf-8"));
}

function computeDiff(current: Record<string,number>, baseline: Record<string,number>): { regressions: string[]; improvements: string[]; unchanged: string[]; worstRegression: number } {
  const regressions: string[] = [];
  const improvements: string[] = [];
  const unchanged: string[] = [];
  let worstRegression = 0;

  for (const [key, baseScore] of Object.entries(baseline)) {
    const currScore = current[key];
    if (currScore === undefined) continue;
    const diff = baseScore - currScore;
    if (diff > REGRESSION_THRESHOLD) {
      regressions.push(`${key}: ${(baseScore*100).toFixed(1)}% → ${(currScore*100).toFixed(1)}% (Δ${(diff*100).toFixed(1)}%)`);
      worstRegression = Math.max(worstRegression, diff);
    } else if (diff > WARN_THRESHOLD) {
      unchanged.push(`${key}: ${(baseScore*100).toFixed(1)}% → ${(currScore*100).toFixed(1)}% (Δ${(diff*100).toFixed(1)}%) ⚠️`);
    } else if (diff < -0.01) {
      improvements.push(`${key}: ${(baseScore*100).toFixed(1)}% → ${(currScore*100).toFixed(1)}% (+${(-diff*100).toFixed(1)}%)`);
    } else {
      unchanged.push(`${key}: ${(baseScore*100).toFixed(1)}% → ${(currScore*100).toFixed(1)}% (stable)`);
    }
  }
  return { regressions, improvements, unchanged, worstRegression };
}

function saveBaseline(run: any) {
  mkdirSync(BASELINE_DIR, { recursive: true });
  const ts = new Date().toISOString().replace(/:/g, "-");
  const catScores: Record<string,number> = {};
  if (run.scores?.by_category) {
    for (const [key, value] of Object.entries(run.scores.by_category as Record<string, {accuracy?: number}>)) {
      if (value?.accuracy !== undefined) catScores[key] = value.accuracy / 100;
    }
  }
  const baseline = {
    timestamp: ts,
    scores: {
      overall: (run.scores?.overall_accuracy ?? 0) / 100,
      ...catScores,
    },
    run_file: run.timestamp || "unknown",
  };
  writeFileSync(join(BASELINE_DIR, `baseline-${ts}.json`), JSON.stringify(baseline, null, 2));
  console.log(`Baseline saved to data/baselines/baseline-${ts}.json`);
  console.log(`  Overall: ${(baseline.scores.overall * 100).toFixed(1)}%`);
}

async function main() {
  const args = process.argv.slice(2);
  const isQuick = args.includes("--quick");
  const baselineOnly = args.includes("--baseline-only");

  console.log("╔══════════════════════════════════════╗");
  console.log("║  ZOU-401: Eval-Driven CI/CD Gate     ║");
  console.log("╚══════════════════════════════════════╝\n");

  // Step 1: Run the benchmark (unless baseline-only)
  if (!baselineOnly) {
    console.log("Running ZouroBench...");
    const cmdArgs = ["run", ADAPTER, "--dataset", SEED, "--judge"];
    if (isQuick) cmdArgs.push("--limit", "15");

    const result = spawnSync("bun", cmdArgs, {
      cwd: BENCH_DIR,
      timeout: 300_000,
      encoding: "utf-8",
      stdio: ["pipe", "pipe", "pipe"],
    });

    if (result.status !== 0) {
      console.error(`Benchmark failed (exit ${result.status}):\n${result.stderr?.slice(0, 500)}`);
      process.exit(3);
    }
    console.log(result.stdout?.split("\n").filter(l => l.includes("accuracy") || l.includes("✓") || l.includes("✗")).join("\n") || "Benchmark completed");
  }

  // Step 2: Load results
  const run = loadLatestRun();
  if (!run) {
    console.error("No benchmark run found");
    process.exit(3);
  }

  const currentScores: Record<string,number> = {
    overall: run.scores?.overall_accuracy ? run.scores.overall_accuracy / 100 : 0,
  };
  if (run.scores?.by_category) {
    for (const [key, value] of Object.entries(run.scores.by_category as Record<string, {accuracy?: number}>)) {
      if (value?.accuracy !== undefined) {
        currentScores[key] = value.accuracy / 100;
      }
    }
  }

  // Step 3: Load baseline and diff
  const baseline = loadBaseline();

  if (!baseline || baselineOnly) {
    saveBaseline(run);
    console.log("\n✅ Baseline established — no gate decision");
    process.exit(0);
  }

  console.log(`\nBaseline: ${baseline.timestamp}`);
  console.log(`  Baseline overall: ${(baseline.scores.overall * 100).toFixed(1)}%`);
  console.log(`  Current overall:  ${(currentScores.overall * 100).toFixed(1)}%\n`);

  // Step 4: Compute diff
  const diff = computeDiff(currentScores, baseline.scores);

  if (diff.regressions.length > 0) {
    console.log("❌ REGRESSIONS (>2%):");
    diff.regressions.forEach(r => console.log(`  ${r}`));
  }

  if (diff.improvements.length > 0) {
    console.log("\n📈 IMPROVEMENTS (>1%):");
    diff.improvements.forEach(i => console.log(`  ${i}`));
  }

  if (diff.unchanged.length > 0) {
    console.log("\n➖ STABLE / MINOR:");
    diff.unchanged.forEach(u => console.log(`  ${u}`));
  }

  // Step 5: Gate decision
  console.log("\n────────────────────────────────────────");
  if (diff.regressions.length > 0) {
    console.log("🚫 GATE: FAIL — Regressions detected");
    console.log(`  Worst regression: ${(diff.worstRegression * 100).toFixed(1)}%`);
    // Still save baseline so next run diffs from here (operator can revert if needed)
    saveBaseline(run);
    process.exit(1);
  } else if (diff.unchanged.some(u => u.includes("⚠️"))) {
    console.log("⚠️  GATE: WARN — Minor drift detected (<2%)");
    saveBaseline(run);
    process.exit(2);
  } else {
    console.log("✅ GATE: PASS — No regressions");
    saveBaseline(run);
    process.exit(0);
  }
}

main();

/**
 * Hermetic env builder for the held-out grader shell-out (P0-3).
 *
 * The held-out examiner is the one process the optimizer must NOT be able to
 * bribe. `runProbe()` historically shelled out with no `env` key, so the child
 * inherited the full parent environment — every secret, every proxy override.
 * That is the reward-hacking surface: a candidate could read ANTHROPIC_* or
 * phone home to fudge its own grade.
 *
 * This builds an allowlist-only env (not a denylist): nothing is forwarded
 * unless it is on the curated trusted list. The grader's retrieval is purely
 * local + deterministic (a /tmp SQLite bank + FTS token overlap), so it needs
 * no secrets, no network, and no embeddings — only enough to (a) run `bun` and
 * (b) resolve its fixture paths.
 *
 * Unlike `buildSandboxEnv` in crystallize/eval-replay.ts (which sets
 * HOME=workspace), the grader needs the REAL HOME so `homedir()` resolves
 * `~/.zouroboros/holdout-fixtures.local.json`. So HOME is preserved verbatim.
 */

import { isSecretEnvName } from '../crystallize/eval-replay.js';

/**
 * Trusted env names copied verbatim from the parent when present. These bypass
 * the secret check by design — ZO_WORKSPACE collides with the ZO_ secret prefix
 * but is a path the grader cannot run without.
 */
export const HOLDOUT_PRESERVE_NAMES = [
  'PATH',
  'HOME',
  'USER',
  'LANG',
  'ZO_WORKSPACE',
  'ZOUROBOROS_DATA_DIR',
  // Control flag the grader child itself reads — must cross the sandbox boundary
  // so an operator's HOLDOUT_SUBCHECKS=0 actually reaches the runner. Non-secret
  // (display-only toggle); forwarding it opens no cheat surface.
  'HOLDOUT_SUBCHECKS',
] as const;

export interface HoldoutSandboxOptions {
  /**
   * Extra parent-env names to forward (escape hatch for a future grader that
   * legitimately needs one more var). Still secret-checked: a name matching a
   * secret prefix/exact is refused even when explicitly requested.
   */
  preserve?: readonly string[];
}

/**
 * Construct the env block for the held-out grader child. Pure — tests assert
 * it directly without spawning.
 */
export function buildHoldoutSandboxEnv(
  parent: NodeJS.ProcessEnv = process.env,
  opts: HoldoutSandboxOptions = {},
): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {};

  // 1. Curated trusted preserve-list — copied verbatim when present.
  for (const name of HOLDOUT_PRESERVE_NAMES) {
    const v = parent[name];
    if (v !== undefined) env[name] = v;
  }

  // 2. Fallbacks for vars the grader cannot start without.
  if (!env.PATH) env.PATH = '/usr/local/bin:/usr/bin:/bin';
  if (!env.LANG) env.LANG = 'C.UTF-8';
  if (!env.USER) env.USER = 'zouroboros';

  // 3. Caller escape hatch — still secret-checked so a stray secret can never
  //    be forwarded, even on explicit request.
  if (opts.preserve) {
    for (const name of opts.preserve) {
      if (isSecretEnvName(name)) continue;
      const v = parent[name];
      if (v !== undefined) env[name] = v;
    }
  }

  // 4. Egress-refusing proxy — set LAST so neither the parent nor opts.preserve
  //    can override it. Port 0 is unbindable ⇒ every outbound connect fails.
  env.HTTPS_PROXY = 'http://127.0.0.1:0';
  env.HTTP_PROXY = 'http://127.0.0.1:0';
  env.NO_PROXY = '';

  return env;
}

#!/usr/bin/env bun
// ponytail-review — single-axis complexity review (Zouroboros DoD COMPLEXITY phase).
//
// Reviews ONE file (or a diff) for over-engineering only. One model call, single
// axis — ~1/3 the cost of the 3-model consensus pass. Advisory: it lists what to
// cut, it never gates anything.
//
// Provider chain: SYNTHETIC_NEW_API_KEY → /zo/ask (ZO_ASK_TOKEN) fallback.
//
//   bun ponytail-review.ts --file <path> [--json] [--model <m>]
//   bun ponytail-review.ts --diff <patch-file> [--json]
//   git diff | bun ponytail-review.ts --stdin --json
//
// JSON shape: { file, model, api, findings: [{loc, tag, what, replacement}], net_lines }

const SYNTHETIC_API = "https://api.synthetic.new/openai/v1/chat/completions";
const ZO_ASK_API = "https://api.zo.computer/zo/ask";
const DEFAULT_MODEL = "hf:zai-org/GLM-5.1";
const VALID_TAGS = ["delete", "stdlib", "native", "yagni", "shrink"] as const;

type Tag = (typeof VALID_TAGS)[number];
interface Finding {
  loc: string;
  tag: Tag | string;
  what: string;
  replacement: string;
}
interface Review {
  file: string;
  model: string;
  api: "synthetic" | "zo-ask" | "none";
  findings: Finding[];
  net_lines: number;
}

function parseArgs(argv: string[]) {
  const a: Record<string, string | boolean> = {};
  for (let i = 0; i < argv.length; i++) {
    const t = argv[i];
    if (t === "--json") a.json = true;
    else if (t === "--stdin") a.stdin = true;
    else if (t === "--help" || t === "-h") a.help = true;
    else if (t === "--file") a.file = argv[++i];
    else if (t === "--diff") a.diff = argv[++i];
    else if (t === "--model") a.model = argv[++i];
  }
  return a;
}

const HELP = `ponytail-review — single-axis complexity review (over-engineering only)

Usage:
  bun ponytail-review.ts --file <path> [--json] [--model <model>]
  bun ponytail-review.ts --diff <patch-file> [--json]
  git diff | bun ponytail-review.ts --stdin [--json]

Finds what to delete: reinvented stdlib, unneeded deps, speculative abstractions,
dead flexibility. One line per finding. Correctness/security/perf are out of scope
(they go to the consensus pass). Advisory only — never gates.

Tags: delete | stdlib | native | yagni | shrink
Provider chain: SYNTHETIC_NEW_API_KEY → /zo/ask (ZO_ASK_TOKEN).`;

function buildPrompt(label: string, content: string): string {
  return `You are a "lazy senior dev" reviewing code for ONE thing only: over-engineering.
Find what to delete, simplify, or replace with a stdlib/native equivalent. You are
SILENT on correctness bugs, security holes, and performance — those go to a different
pass. Do not invent findings; if the code is already lean, return an empty list.

Tags (pick exactly one per finding):
- delete: dead code, unused flexibility, speculative feature. replacement: "nothing".
- stdlib: hand-rolled thing the standard library ships. Name the function.
- native: dependency or code doing what the platform already does. Name the feature.
- yagni: abstraction with one implementation, config nobody sets, layer with one caller.
- shrink: same logic, fewer lines. Show the shorter form.

A single smoke test or assert-based self-check is the minimum, not bloat — never flag it.

Return ONLY a JSON object, no prose, no markdown fences:
{
  "findings": [
    {"loc": "L12-38", "tag": "stdlib", "what": "27-line email validator class", "replacement": "\\"@\\" in email check, 1 line"}
  ],
  "net_lines": 26
}
"loc" is a line or line range like "L12" or "L12-38". "net_lines" is your best estimate
of total lines removable if every finding is applied (a positive integer; 0 if none).

=== ${label} ===
${content}`;
}

function extractJson(output: string): any {
  let s = output.trim();
  const fence = s.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fence) s = fence[1].trim();
  const start = s.indexOf("{");
  const end = s.lastIndexOf("}");
  if (start >= 0 && end > start) s = s.slice(start, end + 1);
  return JSON.parse(s);
}

async function callModel(
  prompt: string,
  model: string,
): Promise<{ output: string; api: Review["api"] }> {
  const syntheticKey = process.env.SYNTHETIC_NEW_API_KEY || "";
  const zoToken = process.env.ZO_ASK_TOKEN || process.env.ZO_TOKEN || "";

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 60000);
  try {
    let resp: Response;
    let api: Review["api"];
    if (syntheticKey) {
      api = "synthetic";
      resp = await fetch(SYNTHETIC_API, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${syntheticKey}`,
          "content-type": "application/json",
        },
        body: JSON.stringify({
          model,
          messages: [{ role: "user", content: prompt }],
          max_tokens: 4096,
        }),
        signal: controller.signal,
      });
    } else if (zoToken) {
      api = "zo-ask";
      resp = await fetch(ZO_ASK_API, {
        method: "POST",
        headers: { authorization: zoToken, "content-type": "application/json" },
        body: JSON.stringify({ input: prompt }),
        signal: controller.signal,
      });
    } else {
      return { output: "", api: "none" };
    }

    if (!resp.ok) {
      throw new Error(`API ${resp.status} ${resp.statusText}`);
    }
    const data: any = await resp.json();
    const msg = data?.choices?.[0]?.message;
    const output = (msg?.content ?? msg?.reasoning_content ?? data?.output ?? "")
      .toString()
      .trim();
    return { output, api };
  } finally {
    clearTimeout(timer);
  }
}

function normalize(raw: any, file: string, model: string, api: Review["api"]): Review {
  const findings: Finding[] = Array.isArray(raw?.findings)
    ? raw.findings
        .map((f: any) => ({
          loc: String(f?.loc ?? f?.line ?? "?"),
          tag: String(f?.tag ?? "shrink"),
          what: String(f?.what ?? "").trim(),
          replacement: String(f?.replacement ?? "").trim(),
        }))
        .filter((f: Finding) => f.what.length > 0)
    : [];
  let net = Number(raw?.net_lines);
  if (!Number.isFinite(net) || net < 0) net = 0;
  return { file, model, api, findings, net_lines: Math.round(net) };
}

function renderText(r: Review): string {
  if (r.api === "none") {
    return `⚠️ ponytail-review: no provider key (SYNTHETIC_NEW_API_KEY or ZO_ASK_TOKEN). Skipped.`;
  }
  const lines: string[] = [];
  lines.push(`ponytail-review · ${r.file} · ${r.model} (${r.api})`);
  if (r.findings.length === 0) {
    lines.push("Lean already. Ship.");
    return lines.join("\n");
  }
  for (const f of r.findings) {
    lines.push(`${f.loc}: ${f.tag}: ${f.what}. ${f.replacement || "nothing"}.`);
  }
  lines.push(`net: -${r.net_lines} lines possible.`);
  return lines.join("\n");
}

async function readStdin(): Promise<string> {
  const chunks: Uint8Array[] = [];
  for await (const chunk of Bun.stdin.stream()) chunks.push(chunk);
  return Buffer.concat(chunks).toString("utf8");
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) {
    console.log(HELP);
    return;
  }

  const model = (args.model as string) || DEFAULT_MODEL;
  let label = "";
  let content = "";
  let fileLabel = "";

  if (args.stdin) {
    content = await readStdin();
    label = "DIFF (stdin)";
    fileLabel = "(stdin)";
  } else if (args.diff) {
    content = await Bun.file(args.diff as string).text();
    label = `DIFF ${args.diff}`;
    fileLabel = args.diff as string;
  } else if (args.file) {
    content = await Bun.file(args.file as string).text();
    label = `FILE ${args.file}`;
    fileLabel = args.file as string;
  } else {
    console.error("error: one of --file, --diff, or --stdin is required (--help for usage)");
    process.exit(2);
  }

  if (!content.trim()) {
    const empty: Review = { file: fileLabel, model, api: "none", findings: [], net_lines: 0 };
    console.log(args.json ? JSON.stringify(empty) : renderText(empty));
    return;
  }

  const prompt = buildPrompt(label, content);
  let review: Review;
  try {
    const { output, api } = await callModel(prompt, model);
    if (api === "none") {
      review = { file: fileLabel, model, api, findings: [], net_lines: 0 };
    } else if (!output) {
      review = { file: fileLabel, model, api, findings: [], net_lines: 0 };
    } else {
      review = normalize(extractJson(output), fileLabel, model, api);
    }
  } catch (err: any) {
    // Advisory phase: a failed review must never break the caller. Report empty.
    console.error(`ponytail-review: ${err.message}`);
    review = { file: fileLabel, model, api: "none", findings: [], net_lines: 0 };
  }

  console.log(args.json ? JSON.stringify(review) : renderText(review));
}

main();
